 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    # The row containing the pair of anchor points is the horizontal spine.
    spine, cols = max(by_row.items(), key=lambda item: len(item[1]))
    lo, hi = min(cols), max(cols)
    for c in range(lo, hi + 1):
        if out[spine][c] == 0:
            out[spine][c] = 3
    # Connect every other point perpendicularly to the spine.
    for r, c in points:
        if r == spine or not (lo <= c <= hi):
            continue
        for rr in range(min(r, spine), max(r, spine) + 1):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
